Yes, it is possible to create a generic changes table that will log only when an UPDATE changes the value of any column, including a JSONB column.

Here's an example of how to create such a table and a corresponding trigger function:


```sql
CREATE TABLE mytable (
 id SERIAL PRIMARY KEY,
 name TEXT,
 data JSONB,
 created_at TIMESTAMP DEFAULT NOW(),
 updated_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE mytable_changes (
 id SERIAL PRIMARY KEY,
 table_name TEXT NOT NULL,
 record_id INTEGER NOT NULL,
 field_name TEXT NOT NULL,
 old_value TEXT,
 new_value TEXT,
 change_date TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE OR REPLACE FUNCTION log_mytable_changes()
RETURNS TRIGGER AS $$
DECLARE
 v_old_data JSONB;
 v_new_data JSONB;
BEGIN
 IF TG_OP = 'UPDATE' THEN
 -- Get the old and new data as JSONB
 v_old_data := row_to_json(OLD)::JSONB;
 v_new_data := row_to_json(NEW)::JSONB;

 -- Loop through each column in the table
 FOR column IN (SELECT column_name, data_type FROM information_schema.columns WHERE table_name = TG_TABLE_NAME) LOOP
 -- Skip the ID and timestamp columns
 IF column.column_name NOT IN ('id', 'created\_at', 'updated\_at') THEN
 -- Get the old and new values as text
 DECLARE
 v_old_value TEXT;
 v_new_value TEXT;
 BEGIN
 IF v_old_data->>column.column_name IS NOT NULL THEN
 v_old_value := v_old_data->>column.column_name;
 ELSE
 v_old_value := '';
 END IF;

 IF v_new_data->>column.column_name IS NOT NULL THEN
 v_new_value := v_new_data->>column.column_name;
 ELSE
 v_new_value := '';
 END IF;
 END;

 -- If the value has changed, log it
 IF v_old_value != v_new_value THEN
 INSERT INTO mytable_changes (table_name, record_id, field_name, old_value, new_value)
 VALUES (TG_TABLE_NAME, OLD.id, column.column_name, v_old_value, v_new_value);
 END IF;
 END IF;
 END LOOP;
 END IF;
 RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER mytable_changes_trigger
AFTER UPDATE ON mytable
FOR EACH ROW EXECUTE FUNCTION log_mytable_changes();
```
